 static S parse(JsonNode x)throws Exception{JsonNode l=x.path("list"),d=x.path("detail"),top=d.path("top");Map<String,String>facts=new LinkedHashMap<>();walk(d,facts);JsonNode ext;try{ext=J.readTree(l.path("ext").asText("{}"));}catch(Exception e){ext=J.createObjectNode();}String loc=l.path("location").asText("");String district=loc.contains("－")?loc.substring(loc.indexOf('－')+1):null;String cur=join(l.path("course"));String grades=join(l.path("stage"));BigDecimal fee=money(first(top.path("tuition").asText(null),l.path("tuition").asText(null)));String tags=limit(first(join(l.path("tag")),l.path("advantage").asText(null)),255);String address=null;if(top.path("address_info").path("list").isArray()){List<String>v=new ArrayList<>();for(JsonNode z:top.path("address_info").path("list"))if(!z.path("address").asText().isBlank())v.add(z.path("address").asText());address=String.join("；",v);}return new S(l.path("id").asInt(),l.path("name").asText(),district,cur,fee,tags,grades,first(ext.path("entrance_progress").asText(null),facts.get("升学情况")),facts.get("寄宿"),first(ext.path("class_size").asText(null),facts.get("班级规模")),facts.get("师生比例"),l.path("logo").asText(null),facts.get("授课方式"),digits(first(facts.get("创办时间"),top.path("found").asText(null))),integer(facts.get("在校学生")),top.path("type").asText(null),limit(address,255),top.path("website_info").path("website").asText(null),l.path("advantage").asText(null),J.writeValueAsString(x));}
 static void walk(JsonNode n,Map<String,String>f){if(n.isObject()){String t=n.path("title").asText(),c=n.path("content").isValueNode()?n.path("content").asText():"";if(!t.isBlank()&&!c.isBlank()&&c.length()<20000)f.putIfAbsent(t,c);if(n.has("list")&&n.path("list").isArray()&&"".equals(c))for(JsonNode q:n.path("list")){String z=q.path("content").asText();if(!t.isBlank()&&!z.isBlank()&&z.length()<500)f.putIfAbsent(t,z);}n.fields().forEachRemaining(e->walk(e.getValue(),f));}else if(n.isArray())for(JsonNode q:n)walk(q,f);}
 static List<Db>load(Connection c)throws Exception{List<Db>x=new ArrayList<>();boolean has=col(c,"school","xueweigui_school_id");try(var s=c.createStatement();var r=s.executeQuery(has?"SELECT id,name,xueweigui_school_id FROM school":"SELECT id,name,NULL xueweigui_school_id FROM school")){while(r.next())x.add(new Db(r.getInt(1),r.getString(2),(Integer)r.getObject(3)));}return x;}interface F{boolean ok(Db d);}static Db unique(List<Db>x,F f){List<Db>m=x.stream().filter(f::ok).toList();return m.size()==1?m.get(0):null;}
 static void schema(Connection c)throws Exception{try(var s=c.createStatement()){if(!col(c,"school","xueweigui_school_id"))s.executeUpdate("ALTER TABLE school ADD COLUMN xueweigui_school_id INT NULL COMMENT '学为贵公开学校ID' AFTER id, ADD UNIQUE KEY uk_school_xueweigui_id (xueweigui_school_id)");s.executeUpdate("CREATE TABLE IF NOT EXISTS school_backup_xueweigui_20260914 AS SELECT * FROM school");s.executeUpdate("CREATE TABLE IF NOT EXISTS xueweigui_school_source (source_id INT PRIMARY KEY,school_name VARCHAR(150) NOT NULL,raw_json JSON NOT NULL,fetched_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) CHARACTER SET utf8mb4");}}
 static boolean col(Connection c,String t,String n)throws Exception{try(var s=c.prepareStatement("SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name=? AND column_name=?")){s.setString(1,t);s.setString(2,n);try(var r=s.executeQuery()){r.next();return r.getInt(1)>0;}}}
 static void stage(Connection c,List<S>x)throws Exception{try(var p=c.prepareStatement("INSERT INTO xueweigui_school_source(source_id,school_name,raw_json) VALUES(?,?,CAST(? AS JSON)) ON DUPLICATE KEY UPDATE school_name=VALUES(school_name),raw_json=VALUES(raw_json),fetched_at=CURRENT_TIMESTAMP")){for(S s:x){p.setInt(1,s.sid);p.setString(2,s.name);p.setString(3,s.raw);p.addBatch();}p.executeBatch();}}
 static void update(Connection c,S s,int id)throws Exception{String q="UPDATE school SET xueweigui_school_id=?,city=COALESCE(NULLIF(city,''),'上海'),district=COALESCE(NULLIF(district,''),?),curriculum=COALESCE(NULLIF(curriculum,''),?),tuition_min=COALESCE(tuition_min,?),tuition_max=COALESCE(tuition_max,?),feature_tags=COALESCE(NULLIF(feature_tags,''),?),grades=COALESCE(NULLIF(grades,''),?),graduation_result=COALESCE(NULLIF(graduation_result,''),?),boarding_info=COALESCE(NULLIF(boarding_info,''),?),class_size=COALESCE(NULLIF(class_size,''),?),teacher_ratio=COALESCE(NULLIF(teacher_ratio,''),?),logo_url=COALESCE(NULLIF(logo_url,''),?),teaching_mode=COALESCE(NULLIF(teaching_mode,''),?),founding_time=COALESCE(NULLIF(founding_time,''),?),student_count=COALESCE(student_count,?),school_type=COALESCE(NULLIF(school_type,''),?),address=COALESCE(NULLIF(address,''),?),official_website=COALESCE(NULLIF(official_website,''),?),teaching_features=COALESCE(NULLIF(teaching_features,''),?),is_active=COALESCE(is_active,1) WHERE id=?";try(var p=c.prepareStatement(q)){bind(p,s);p.setInt(20,id);p.executeUpdate();}}
 static void insert(Connection c,S s)throws Exception{String q="INSERT INTO school(xueweigui_school_id,name,city,district,curriculum,tuition_min,tuition_max,feature_tags,grades,graduation_result,boarding_info,class_size,teacher_ratio,logo_url,is_active,teaching_mode,founding_time,student_count,school_type,address,official_website,teaching_features)VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)";try(var p=c.prepareStatement(q)){int i=1;p.setInt(i++,s.sid);p.setString(i++,s.name);p.setString(i++,"上海");p.setString(i++,s.district);p.setString(i++,s.curriculum);p.setBigDecimal(i++,s.fee);p.setBigDecimal(i++,s.fee);p.setString(i++,s.tags);p.setString(i++,s.grades);p.setString(i++,s.grad);p.setString(i++,s.board);p.setString(i++,s.cls);p.setString(i++,s.ratio);p.setString(i++,s.logo);p.setInt(i++,1);p.setString(i++,s.mode);p.setString(i++,s.founded);if(s.students==null)p.setNull(i++,Types.INTEGER);else p.setInt(i++,s.students);p.setString(i++,s.type);p.setString(i++,s.address);p.setString(i++,s.website);p.setString(i,s.features);p.executeUpdate();}}
