 static String n(String s){return s.replaceFirst("^上海市?","").replaceAll("[\\s·•()（）《》【】\\-—_/]","").toLowerCase();}static String join(JsonNode a){if(!a.isArray())return null;List<String>x=new ArrayList<>();for(JsonNode n:a)if(!n.asText().isBlank())x.add(n.asText());return x.isEmpty()?null:String.join(",",x);}static String first(String a,String b){return a!=null&&!a.isBlank()?a:b;}static String limit(String s,int n){return s==null?null:s.substring(0,Math.min(n,s.length()));}static String digits(String s){if(s==null)return null;var m=Pattern.compile("(?:19|20)\\d{2}").matcher(s);return m.find()?m.group():limit(s,50);}static Integer integer(String s){if(s==null)return null;var m=Pattern.compile("\\d+").matcher(s.replace(",",""));return m.find()?Integer.valueOf(m.group()):null;}static BigDecimal money(String s){if(s==null)return null;var m=Pattern.compile("(\\d+(?:\\.\\d+)?)").matcher(s);return m.find()?new BigDecimal(m.group(1)):null;}
 static String v(String y,String k){var m=Pattern.compile("(?m)^\\s*"+k+":\\s*([^\\r\\n#]+)").matcher(y);if(!m.find())throw new IllegalStateException(k);String z=m.group(1).trim();var p=Pattern.compile("\\$\\{([^:}]+)(?::([^}]*))?}").matcher(z);if(!p.matches())return z;String e=System.getenv(p.group(1));return e!=null&&!e.isBlank()?e:p.group(2);}
